                                                                                                                                                                                                       
  CREATE TABLE "CHECK_PUSH_USER_CONFIG"                                                                                                                                                     
   (	"CONFIG_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"EXT_USER_ID" NUMBER(20,0),                                                                                                                                                                           
	"FAB_ID" NUMBER(20,0),                                                                                                                                                                                
	"EXT_ORG_ID" NUMBER(20,0),                                                                                                                                                                            
	"MAP_AREA_X_ID" NVARCHAR2(500),                                                                                                                                                                       
	"MAP_AREA_Y_ID" NVARCHAR2(500),                                                                                                                                                                       
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                    
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                     
	"REMARK" NVARCHAR2(512),                                                                                                                                                                              
	"TENANT_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                             
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"CREATION_DATE" DATE DEFAULT SYSDATE NOT NULL ENABLE,                                                                                                                                                 
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"UPDATED_DATE" DATE DEFAULT SYSDATE NOT NULL ENABLE,                                                                                                                                                  
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                         
	 PRIMARY KEY ("CONFIG_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                  
   ) ;                                                                                                                                                                                                 

